6861     std::swap(A, B);
6862     [[fallthrough]];
6863   case ICmpInst::ICMP_ULE:
6864     // icmp ule i1 A, B -> ~A | B
6865     return BinaryOperator::CreateOr(Builder.CreateNot(A), B);
